// If no client data...

if (!$input.item.json.cellphone) {
    $input.item.json.cellphone = $('WhatsApp Trigger').first().json.contacts[0].wa_id;
    $input.item.json.email = "";
    $input.item.json.first_name = "";
    $input.item.json.last_name = "";
    $input.item.json.onboarded = false
    $input.item.json.preferred_name = $('WhatsApp Trigger').first().json.contacts[0].profile.name;
    $input.item.json.sex = "X";
    $input.item.json.def_lang = "en";
}

return $input.item;

const d = new Date($json.currentDate);

const r = {
    "current_datetime": new Intl.DateTimeFormat("en-CA", {
        dateStyle: "full",
        timeStyle: "long",
        timeZone: "America/Toronto",
    }).format(d)
}

return r;
